document.addEventListener('click',e=>{const suggestion=e.target.closest('[data-action="search-suggest"]');if(!suggestion)return;e.preventDefault();e.stopImmediatePropagation();const form=$('#search-global');if(form){form.elements.q.value=suggestion.dataset.id;form.requestSubmit();}},true);
document.addEventListener('change',e=>{if(e.target.name==='apps'){const id=e.target.value;if(e.target.checked&&!customDraft.includes(id))customDraft.push(id);if(!e.target.checked)customDraft=customDraft.filter(x=>x!==id);customEditor();return;}if(e.target.id==='role'){state.role=e.target.value;audience='all';save();if($('#modal').open)$('#modal').close();render();toast('已切换为'+roles[state.role]+'身份');}});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}const used=e.target.closest('[data-service]');if(used){const service=allServices.find(s=>s.id===used.dataset.service);if(service&&canViewService(state.role,service)){recordUse(state,state.role,service.id);save();}}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id||'';try{requireAction(state.role,a);
if(a==='feedback-new'||a==='feedback-edit'){const d=state.feedbackDrafts.find(x=>x.id===id);modal(d?'编辑反馈草稿':'写反馈','草稿保存在本机。复制草稿后，通过意见反馈提交。',`<label>反馈类型<select name="category">${opts(['服务建议','使用问题','其他'],d?.category||'服务建议')}</select></label>${field('标题','title',d?.title||'')}${area('反馈内容','body',d?.body||'')}`,'feedback-form',`data-feedback="${d?.id||''}"`);return;}
if(a==='feedback-copy'){const d=state.feedbackDrafts.find(x=>x.id===id);if(!d)throw Error('反馈草稿不存在');navigator.clipboard.writeText(`${d.category}：${d.title}\n${d.body}`).then(()=>toast('已复制，请在咨询留言入口发送')).catch(()=>error(Error('无法复制，请选中草稿内容手动复制。')));return;}
if(a==='close'){$('#modal').close();return;}if(a==='audience'){if(id!=='all'&&!roles[id])return;if(route==='services'){params.set('audience',id);params.delete('source');if(params.get('primary')==='推荐服务'){params.delete('primary');params.delete('cat');}go('services?'+params);}else{audience=id;render();}return;}if(a==='quick-mode'){if(!quickModes[id])return;setMode(state,state.role,id);save();render();return;}if(a==='customize'){customDraft=(ensurePortal(state).custom[state.role]||[]).slice();customEditor();return;}if(a==='custom-up'||a==='custom-down'){const i=customDraft.indexOf(id),j=i+(a==='custom-up'?-1:1);if(i>=0&&j>=0&&j<customDraft.length)[customDraft[i],customDraft[j]]=[customDraft[j],customDraft[i]];customEditor();return;}if(a==='custom-restore'){setCustom(state,state.role,quickApps(state,originalServices,state.role,'default',contentConfig.recommendedOrder).map(s=>s.id));setMode(state,state.role,'default');save();$('#modal').close();render();return;}if(a==='scope'){scope=id;searchComposing=false;render();return;}if(a==='guide'){guide();return;}if(a==='favorite'){const f=state.favorites[state.role]??=[];const i=f.indexOf(id);if(i<0)f.push(id);else f.splice(i,1);save();render();toast(i<0?'已加入我的收藏':'已取消收藏');return;}if(a==='consult'){requestModal('咨询留言',id||'','');return;}if(a==='request'){requestModal('馆际互借与文献传递',id||'', '');return;}if(a==='request-service'){const s=allServices.find(x=>x.id===id);requestModal('咨询留言',s.name+'服务咨询','我希望了解此项服务的办理条件。');return;}if(a==='request-resource'){const r=getResource(id);requestModal('馆际互借与文献传递',r.title,`题名：${r.title}\n作者：${r.author}\n年份：${r.year}\n来源：${r.source}\n已尝试的渠道：\n希望获取：`);return;}if(a==='new-project'||a==='edit-project'){const p=state.projects.find(x=>x.id===id&&x.owner===state.role);modal(p?'编辑研学助手':'研学助手','项目资料仅属于当前身份。',field('项目名称','title',p?.title||'')+area('研究问题','question',p?.question||'',false),'project-form',`data-project="${p?.id||''}"`);return;}if(a==='add-ref'||a==='note-resource'){const ps=ownProjects();if(!ps.length){modal('先建立一个研学助手','创建后会自动将这篇文献加入文献夹。',`<input type="hidden" name="resourceId" value="${id}"><input type="hidden" name="next" value="${a}">${field('项目名称','title')}${area('研究问题','question','',false)}`,'project-form');return;}modal(a==='add-ref'?'加入文献夹':'选择笔记所属项目','选择项目后可继续整理。',`<input type="hidden" name="resourceId" value="${id}"><input type="hidden" name="next" value="${a}"><label>研学助手<select name="projectId">${opts(ps.map(p=>[p.id,p.title]),ps[0].id)}</select></label>`,'add-ref-form');return;}if(a==='remove-ref'){const [pid,rid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);if(!p)throw Error('没有权限');p.refs=p.refs.filter(x=>x!==rid);save();render();toast('已从文献夹移除，笔记仍保留');return;}if(['new-note','edit-note','note-resource'].includes(a)){const [pid,nid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);noteModal(p,'',p?.notes.find(n=>n.id===nid));return;}if(a==='delete-note'){const [pid,nid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);if(!p)throw Error('无权操作');modal('删除这条笔记？','删除后无法恢复，请确认已保存所需内容。',btn('确认删除','confirm-delete-note',id,'danger'));return;}if(a==='confirm-delete-note'){const [pid,nid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);p.notes=p.notes.filter(n=>n.id!==nid);save();$('#modal').close();render();return;}
if(a==='cite'){const r=getResource(id);modal('引用导出与字段核对','按来源记录整理书目信息，使用前请核对发表版本。',`<pre class="pre">${esc(citation(r))}</pre>${btn('下载引用文本','export-one',id,'primary')}`);return;}if(a==='export-one'){download('文献引用.txt',''+citation(getResource(id)));return;}if(a.startsWith('export-')){const p=state.projects.find(p=>p.id===id&&p.owner===state.role),refs=p?.refs.map(getResource).filter(Boolean)||[];if(a==='export-state')download('智慧图书馆-本地数据.json',JSON.stringify(state,null,2),'application/json');if(a==='export-outline'&&p)download(p.title+'-开题提纲.md',outline(p.outline));if(a==='export-matrix'&&p)download(p.title+'-综述矩阵.csv','\uFEFF'+csv([['文献','研究问题','材料','方法','核心观点','待核对'],...refs.map(r=>[r.title,...['question','material','method','argument','check'].map(k=>p.matrix[r.id]?.[k]||'')])]),'text/csv;charset=utf-8');if((a==='export-citations'||a==='export-bib')&&p)download(p.title+(a==='export-bib'?'.bib':'-引用.txt'),''+refs.map(r=>citation(r,a==='export-bib'?'bib':'gb')).join('\n\n'));if(a==='export-ticket'){const t=state.tickets.find(t=>t.id===id&&(t.owner===state.role||['librarian','manager'].includes(state.role)));if(t)download(t.no+'-处理记录.txt',`${t.title}\n${t.status}\n\n`+t.history.map(h=>`${h.time} ${roles[h.by]} ${h.action}\n${h.text}`).join('\n\n'));}return;}
if(a==='new-course'){if(state.role!=='teacher')throw Error('请切换教职工身份');modal('创建课程文献中心','建立课程与书目，再向馆员提出补充方向。',field('课程名称','title')+area('课程简介 / 学期','description','',false),'course-form');return;}if(a==='course-add'){const c=state.courses.find(c=>c.id===id&&c.owner===state.role);if(!c)throw Error('无权操作');modal('向课程添加书目','可多选公开文献。正式书单需核对实际书目信息。',resources.map(r=>`<label style="display:flex;align-items:center;gap:12px"><input type="checkbox" name="refs" value="${r.id}" ${c.refs.includes(r.id)?'checked':''}>${esc(r.title)}</label>`).join(''),'course-add-form',`data-course="${id}"`);return;}if(a==='course-remove'){const [cid,rid]=id.split('|'),c=state.courses.find(c=>c.id===cid&&c.owner===state.role);if(!c)throw Error('没有权限');c.refs=c.refs.filter(x=>x!==rid);save();render();return;}if(a==='course-request'){const c=state.courses.find(c=>c.id===id&&c.owner===state.role);if(!c)throw Error('没有权限');requestModal('课程书单补充',c.title+' · 书单补充',`课程：${c.title}\n已有书目：${c.refs.map(r=>getResource(r)?.title).join('、')||'暂无'}\n希望补充的方向：`,c.id);return;}
if(a==='reserve'){modal('预约'+esc(id),'可登记时段 08:00—22:00；重叠会提示冲突。',`<input type="hidden" name="room" value="${esc(id)}">${field('日期','date',today(),'date')}<div class="form-grid inline">${field('开始时间','start','09:00','time')}${field('结束时间','end','10:00','time')}</div><div class="notice">时段登记面向在校生与教职工；实际预约须通过官方系统。</div>`,'reservation-form');return;}if(a==='cancel-reservation'){const booking=state.reservations.find(r=>r.id===id);cancelReservation(state,route==='workspace'&&booking?booking.owner:state.role,id);save();render();toast('本页预约记录已取消');return;}
if(a.startsWith('ticket-')){const action=a.slice(7);if(action==='accept'||action==='confirm'){transition(state,state.role,id,action);save();render();toast(action==='accept'?'已受理，请继续处理':'已确认解决');return;}const labels={need:'要求补充材料',reply:'回复处理结果',supplement:'补充材料',reopen:'继续提问'};modal(labels[action],'内容会保存到申请时间线，申请人和馆员均可查看。',`<input type="hidden" name="ticketId" value="${id}"><input type="hidden" name="action" value="${action}">${area('内容','text')}`,'transition-form');return;}
if(a==='subscribe'){modal('保存订阅意向','此不发送通知，只在工作台保存主题。',`<input type="hidden" name="type" value="${esc(id||'检索订阅')}">${field('期刊名称或主题检索式','title')}`,'subscribe-form');return;}if(a==='unsubscribe'){state.subscriptions=state.subscriptions.filter(s=>s.id!==id||s.owner!==state.role);save();render();return;}if(a==='register'){const i=state.registrations.findIndex(r=>r.eventId===id&&r.owner===state.role);if(i<0)state.registrations.push({eventId:id,owner:state.role});else state.registrations.splice(i,1);save();render();toast(i<0?'已保存报名':'已取消报名');return;}if(a==='reset'){modal('重置当前浏览器的本地数据？','这会清除当前浏览器的项目、申请与时段记录。请先导出备份。',`<div class="actions">${btn('先导出本地数据','export-state')}${btn('确认清空本地数据','confirm-reset','','danger')}</div>`);return;}if(a==='confirm-reset'){const role=state.role;state=initialState();state.role=role;save();$('#modal').close();go('home');render();toast('本地数据已清空');return;}
}catch(e){error(e);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd),submit=f.querySelector('button[type="submit"],button:not([type])');try{if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true');}if(f.id==='search-global'){submitHomeSearch(v);return;}if(['resource-search','resource-filter','service-search','help-search','tool-search','project-search','journal-form'].includes(f.id)){const r={'resource-search':'discover','resource-filter':'discover','service-search':'services','help-search':'help','tool-search':'tools','project-search':`project/${f.dataset.project}?tab=knowledge`,'journal-form':'research?tab=journals'}[f.id];const q=new URLSearchParams(v);if(f.id==='resource-filter'&&v.fav)q.set('fav','1');go(r+(r.includes('?')?'&':'?')+q);return;}
if(f.id==='feedback-form'){const title=String(v.title||'').trim(),body=String(v.body||'').trim();if(!title||!body)throw Error('请填写标题和反馈内容');const record={id:f.dataset.feedback||uid(),category:v.category||'服务建议',title,body,time:stamp()};const index=state.feedbackDrafts.findIndex(d=>d.id===record.id);if(index<0)state.feedbackDrafts.unshift(record);else state.feedbackDrafts[index]=record;save();$('#modal').close();go('workspace?tab=feedback');render();toast('反馈草稿已保存，尚未发送');return;}
if(f.id==='custom-apps-form'){const allowed=new Set(filterApps(originalServices,state.role).map(s=>s.id));const ids=fd.getAll('apps');if(ids.some(id=>!allowed.has(id)))throw Error('包含当前身份不可用的应用');setCustom(state,state.role,ids);setMode(state,state.role,'custom');save();$('#modal').close();render();toast('我的常用已保存');return;}if(f.id==='request-form'){const t=createTicket(state,state.role,v);save();$('#modal').close();go('ticket/'+t.id);toast('申请已提交，可切换馆员处理');return;}if(f.id==='project-form'){let p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!v.title.trim())throw Error('请填写项目名称');if(p){p.title=v.title.trim();p.question=v.question.trim();}else{p={id:uid(),owner:state.role,title:v.title.trim(),question:v.question.trim(),refs:v.resourceId?[v.resourceId]:[],notes:[],matrix:{},outline:{}};state.projects.unshift(p);}save();$('#modal').close();if(v.next==='note-resource'){render();noteModal(p,v.resourceId);}else{go('project/'+p.id);toast('研学助手已保存');}return;}if(f.id==='add-ref-form'){const p=state.projects.find(p=>p.id===v.projectId&&p.owner===state.role);if(!p)throw Error('项目不存在');if(!p.refs.includes(v.resourceId))p.refs.push(v.resourceId);save();$('#modal').close();if(v.next==='note-resource')noteModal(p,v.resourceId);else toast('已加入文献夹');return;}if(f.id==='note-form'){const p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!p)throw Error('项目不存在');const n={...v,id:f.dataset.note||uid(),time:stamp()};if(f.dataset.note)p.notes=p.notes.map(x=>x.id===n.id?n:x);else p.notes.unshift(n);save();$('#modal').close();go(`project/${p.id}?tab=notes`);render();toast('阅读笔记已保存');return;}if(f.id==='matrix-form'){const p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!p)throw Error('项目不存在');for(const r of p.refs){p.matrix[r]??={};for(const k of ['question','material','method','argument','check'])p.matrix[r][k]=v[`${r}_${k}`]||'';}save();toast('综述矩阵已保存');return;}if(f.id==='outline-form'){const p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!p)throw Error('项目不存在');p.outline=v;save();render();toast('已保存并更新完整性检查');return;}if(f.id==='course-form'){if(state.role!=='teacher')throw Error('仅教职工可创建');if(!v.title.trim())throw Error('请填写课程名称');state.courses.unshift({id:uid(),owner:state.role,title:v.title.trim(),description:v.description,refs:[]});save();$('#modal').close();render();toast('课程文献中心已创建');return;}if(f.id==='course-add-form'){const c=state.courses.find(c=>c.id===f.dataset.course&&c.owner===state.role);if(!c)throw Error('无权操作');c.refs=fd.getAll('refs').filter(id=>getResource(id));save();$('#modal').close();render();toast('课程书目已更新');return;}if(f.id==='reservation-form'){reserve(state,state.role,v);save();$('#modal').close();go('workspace?tab=reservations');toast('时段登记已保存');return;}if(f.id==='transition-form'){transition(state,state.role,v.ticketId,v.action,v.text);save();$('#modal').close();render();toast('处理记录已更新');return;}if(f.id==='subscribe-form'){if(!v.title.trim())throw Error('请填写订阅主题');state.subscriptions.push({...v,id:uid(),owner:state.role});save();$('#modal').close();go('workspace?tab=subscriptions');toast('订阅意向已保存，未启用推送');return;}
}catch(e){error(e);}finally{if(submit){submit.disabled=false;submit.removeAttribute('aria-busy');}}});
function csv(rows){return rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const n=JSON.parse(e.newValue);if(n?.version===1){if($('#modal').open)$('#modal').close();state=migrateRoles(n);render();toast('已同步此浏览器另一标签页的操作记录');}}catch{}}});
render();


function customEditor(){const available=filterApps(originalServices,state.role);customDraft=customDraft.filter(id=>available.some(s=>s.id===id));const ordered=[...customDraft.map(id=>available.find(s=>s.id===id)),...available.filter(s=>!customDraft.includes(s.id))];modal('我的常用','最多选择 9 个应用，已选项目可调整顺序。',`<div class="custom-editor"><div class="custom-editor-bar"><span>已选择 ${customDraft.length} / 9</span>${btn('恢复推荐应用','custom-restore','','small')}</div>${ordered.map(s=>`<div class="custom-app-row"><label><input type="checkbox" name="apps" value="${s.id}" ${customDraft.includes(s.id)?'checked':''}><span>${esc(s.name)}</span></label>${customDraft.includes(s.id)?`<div class="custom-order">${btn('↑','custom-up',s.id,'small')}${btn('↓','custom-down',s.id,'small')}</div>`:''}</div>`).join('')}</div>`,'custom-apps-form');}

async function loadCatalog(){
 const configured=document.querySelector('meta[name="nju-catalog-endpoint"]')?.content;
 // Static hosts use the packaged configuration. A managed host can expose the public API.
 const localApi=location.hostname==='localhost'||location.hostname==='127.0.0.1';
 for(const path of [...(configured?[configured]:localApi?['./api/catalog']:[]),'./service-content.json']){
  try{
   const response=await fetch(new URL(path,location.href),{cache:'no-store'});
   if(!response.ok)continue;
   setCatalog(await response.json());
   const input=document.querySelector(searchInput);
   const restoreInput=document.activeElement===input&&input;
   if($('#modal').open)return;
   render();
   if(restoreInput){
    const current=document.querySelector(searchInput);
    current.value=input.value;
    current.focus({preventScroll:true});
    current.setSelectionRange(input.selectionStart,input.selectionEnd);
    updateSearchHints(current);
   }
   return;
  }catch{}
 }
}
if(location.protocol==='http:'||location.protocol==='https:')void loadCatalog();

